head.script:
scwin.onLoadComplete = function() {
    var jsonObj = {
        'messageBody': {
            'dataMpa1_key1': 'a',
            'dataMpa1_key2': 'b',
            'dataMpa1_key3': 'c',
            'mapObject': {
                'dataMpa2_key1': '1',
                'dataMpa2_key2': '2',
                'dataMpa2_key3': '3'
            },
            'listObject': [{
                'col1': 'AA',
                'col2': 'BB'
            }, {
                'col1': 'CC',
                'col2': 'DD'
            }]
        }
    };
    txa_jsonStr.setValue(JSON.stringify(jsonObj, null, 2));
};
scwin.trigger1_onclick = function(e) {
    var jsonObj = $p.data.get('json', [{
        'id': 'dataMap1',
        'key': 'messageBody'
    }, 'dataList1', 'dataMap2']);
    alert(JSON.stringify(jsonObj, null, 2));
};
scwin.trigger2_onclick = function(e) {
    var jsonObj = $p.data.get('json', ['dataList1', 'dataMap2', {
        'id': 'dataMap1',
        'key': 'messageBody'
    }]);
    window.data1 = JSON.stringify(jsonObj, null, 2);
};
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Verify step 1. The dataList1 value is shown first and the dataMap2 value is shown.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "data1.indexOf('dataList1') == '26'", "true");
    WebSquare.wUnit.addCommand("assert", "data1.indexOf('dataMap2') == '223'", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.onLoadComplete();
    //window.data1;
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 08-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
